INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64505257', 64505257, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL KESEHATAN PRIMER DAN KOMUNITAS', 'Kursi Gigi', 'Barang', 'Tender', 'DKI Jakarta, Jakarta Selatan (Kota)', 38752000000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 0, 0, '865', 'Kursi Gigi', 'A complete Dental Delivery Unit system includes: a. Dental Delivery Unit b. Dental Chair c. Medical Air Compressors d. Central Vacuum Pumps Equipment combined in a single unit designed to deliver dental care. These units typically combine all the fundamental devices needed to provide dental services, such as handpieces, lights, and cuspidors; they also include the supplies needed for their operation, such as compressed air, suction, electricity, and water. Dental delivery units are frequently available as stand-alone units, but some units are attached to a dental chair. Dental delivery units are the main component of dental systems that may also include x-ray devices, cabinets, stools, sterilization units, and other ancillary equipment. Procedure chairs designed to facilitate dental examination, treatment, and/or minor surgical procedures. These chairs are typically adjustable up to a height that allows the healthcare staff to perform procedures while standing; the chairs usually include head- and armrests, a back that may be tilted from a vertical to near-horizontal position, and rotating capabilities to facilitate examination and/or treatment. The chairs may be mechanically operated or hydraulic or electrically powered; some chairs can be programmed for several standard positions.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1620265);
